<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request } from '../api'
type Job=Record<string,any>
const rows=ref<Job[]>([]),config=ref<Job>({}),busy=ref(false),error=ref(''),notice=ref('')
const names:Record<string,string>={queued:'В очереди',sending:'Отправляется',sent:'Принято провайдером',failed:'Ошибка отправки',cancelled:'Отменено'}
const kinds:Record<string,string>={registered:'Получение заявки',approved:'Подтверждение участия',rejected:'Отказ',test:'Тестовое письмо'}
const delivery:Record<string,string>={sent:'Принято к отправке',delivered:'Доставлено почтовому серверу',delivery_delayed:'Доставка задержана',bounced:'Письмо отклонено получателем',complained:'Жалоба на спам',opened:'Открыто',clicked:'Переход по ссылке',failed:'Ошибка доставки',suppressed:'Отправка заблокирована',unknown:'Неизвестно',canceled:'Отменено'}
const date=(value:string|number)=>value?new Date(value).toLocaleString('ru-RU'):'—'
async function work(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Не удалось выполнить действие'}finally{busy.value=false}}
async function load(){const result=await Promise.all([request('admin/mail'),request('admin/mail/config')]);rows.value=result[0];config.value=result[1]}
async function run(){if(!confirm('Обработать очередь? Будет сделано до 10 попыток отправки готовых писем.'))return;await work(async()=>{const result=await request('admin/mail/run',{method:'POST',body:'{}'});await load();notice.value=result.disabled?'Отправка отключена: сначала подключите провайдера и включите письма в настройках.':`Выполнено попыток: ${result.processed}. Это не подтверждение доставки. Нажмите «Проверить доставку» у нужного письма.`})}
function canRetry(job:Job){return ['queued','failed','sending'].includes(job.state)&&(!job.first_attempt_at||Date.now()-job.first_attempt_at<23*3600000)&&(job.state!=='sending'||job.lease_until<=Date.now())}
function needsReconciliation(job:Job){return ['queued','failed','sending'].includes(job.state)&&job.first_attempt_at&&Date.now()-job.first_attempt_at>=23*3600000}
async function action(job:Job,action:'retry'|'resend'|'delivery'){
 if(action==='resend'&&!confirm(job.state==='sent'?'Создать новое письмо этому гостю? Предыдущее уже принято провайдером; гость получит ещё одно письмо.':'Вы проверили в Resend результат прошлой попытки и подтверждаете отправку нового письма этому гостю? Возможен дубль, если прежнее письмо было доставлено.'))return
 await work(async()=>{const result=await request(`admin/mail/${encodeURIComponent(job.id)}/${action}`,{method:'POST',body:JSON.stringify({requestKey:crypto.randomUUID(),confirm:action==='resend',reconciled:action==='resend'&&job.state!=='sent'})});await load();notice.value=action==='delivery'?'Статус провайдера: '+(delivery[result.status]||result.status):'Письмо поставлено в очередь. Для отправки нажмите «Обработать очередь».'})
}
onMounted(()=>work(load))
</script>
<template>
<section class="admin-workflow" :aria-busy="busy"><h2>Очередь писем</h2>
 <p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
 <div class="workflow-panel"><h3>{{config.ready?'Отправка готова':'Отправка не подключена или выключена'}}</h3><p>Провайдер: {{config.provider==='resend'?'Resend':'отключён'}} · API-ключ: {{config.keyConfigured?'настроен':'не настроен'}} · Разрешение отправки: {{config.enabled?'включено':'выключено'}}</p><p>Отправитель: {{config.from||'не указан'}}<br>Сайт в письмах: {{config.siteUrl||'не задан (PUBLIC_ORIGIN)'}}</p><p>Адрес отправителя и разрешение отправки меняются в «Настройках». Для подключения нужны Resend с подтверждённым доменом, MAIL_PROVIDER=resend и секрет RESEND_API_KEY в настройках Cloudflare Worker. Ключ в админке не показывается.</p></div>
 <div class="actions"><button class="primary" :disabled="busy||!config.ready" @click="run">Обработать очередь — до 10 писем</button><button :disabled="busy" @click="work(load)">Обновить список</button></div>
 <details><summary>Как работают отправка и повтор</summary><p>Новая заявка создаёт письмо registered. Одобрение — approved. Отказ — rejected, если включён в настройках. Шаблон копируется в очередь в момент события. Сохранение шаблона не меняет уже созданные письма.</p><p>Обработка очереди запускается этой кнопкой; фонового расписания в этой сборке нет. После ошибки следующая попытка доступна через 2, 4, 8, 16 минут (до 5 попыток). Время следующей попытки указано в строке. После двух минут незавершённая попытка может быть восстановлена при следующей обработке.</p><p>«Повторить попытку» возвращает то же письмо в очередь с защитой от дублей и неизменным содержимым. После 23 часов результат нужно сначала сверить в Resend. «Отправить ещё раз» создаёт новое письмо по сохранённому тексту, с актуальными данными гостя, и может привести к дублю.</p><p>«Принято провайдером» не равно доставке. «Проверить доставку» запрашивает последний статус Resend. Событие «Доставлено» означает приём сервером получателя, а не гарантированное попадание во «Входящие». Проверка обновляется вручную.</p></details>
 <p>Показаны последние 100 заданий. Для сверки писем откройте <a href="https://resend.com/emails" target="_blank" rel="noopener">Resend → Emails ↗</a> и найдите письмо по ID провайдера или адресу гостя.</p>
 <div class="table-wrap"><table><thead><tr><th>Гость / письмо</th><th>Отправка</th><th>Доставка</th><th>Попытки / ошибка</th><th>Действия</th></tr></thead><tbody><tr v-for="job in rows" :key="job.id"><td>{{job.recipient||'—'}}<small>{{kinds[job.kind.split(':')[0]]||job.kind}}{{job.kind.includes(':resend:')?' · повторное письмо':''}}</small><small>Создано: {{date(job.created_at)}}</small><small>ID: {{job.id}}</small></td><td>{{names[job.state]||job.state}}<small v-if="job.state==='queued'">Доступно с: {{job.available_at?date(job.available_at):'сейчас'}}</small><small v-if="needsReconciliation(job)">Нужна ручная сверка: окно безопасного повтора истекло.</small></td><td>{{delivery[job.delivery_status]||job.delivery_status||'Не проверялась'}}<small v-if="job.provider_id">ID провайдера: {{job.provider_id}}</small><small v-if="job.delivery_checked_at">Проверено: {{date(job.delivery_checked_at)}}</small></td><td>{{job.attempts}}<small>{{job.last_error||'Без ошибки'}}</small></td><td><button v-if="job.provider_id" :disabled="busy||!config.keyConfigured" @click="action(job,'delivery')">Проверить доставку</button><button v-if="canRetry(job)" :disabled="busy" @click="action(job,'retry')">Повторить попытку</button><button v-if="job.state==='sent'||(needsReconciliation(job)&&(job.state!=='sending'||job.lease_until<=Date.now()))" :disabled="busy" @click="action(job,'resend')">Отправить ещё раз</button></td></tr></tbody></table></div><p v-if="!busy&&!rows.length">Очередь пуста.</p>
</section>
</template>
<style scoped lang="scss" src="../admin-workflow.scss"></style>
